package vn.iotstar.controller;import jakarta.validation.Valid;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import vn.iotstar.dto.UserDTO;import vn.iotstar.service.UserService;@Controller @RequestMapping("/users") public class UserController{public UserController(UserService service){this.service=service;}final UserService service;@GetMapping public String list(@RequestParam(defaultValue="")String keyword,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size,Model m){m.addAttribute("users",service.findAll(keyword,page,size));m.addAttribute("keyword",keyword);m.addAttribute("size",size);return "users/list";}@GetMapping("/create")public String create(Model m){UserDTO d=new UserDTO();d.setEnabled(true);d.setRoleName("ROLE_USER");m.addAttribute("userDTO",d);m.addAttribute("mode","create");return "users/form";}@PostMapping("/create")public String create(@Valid @ModelAttribute UserDTO d,BindingResult r,Model m,RedirectAttributes a){if(r.hasErrors()){m.addAttribute("mode","create");return "users/form";}try{service.create(d);a.addFlashAttribute("success","Tạo user thành công. Mật khẩu mặc định: 123456");return "redirect:/users";}catch(IllegalArgumentException e){r.reject("user.error",e.getMessage());m.addAttribute("mode","create");return "users/form";}}@GetMapping("/edit/{id}")public String edit(@PathVariable Long id,Model m){m.addAttribute("userDTO",service.findById(id));m.addAttribute("mode","edit");return "users/form";}@PostMapping("/edit/{id}")public String edit(@PathVariable Long id,@Valid @ModelAttribute UserDTO d,BindingResult r,Model m,RedirectAttributes a){if(r.hasErrors()){m.addAttribute("mode","edit");return "users/form";}try{service.update(id,d);a.addFlashAttribute("success","Cập nhật user thành công.");return "redirect:/users";}catch(IllegalArgumentException e){r.reject("user.error",e.getMessage());m.addAttribute("mode","edit");return "users/form";}}@PostMapping("/delete/{id}")public String delete(@PathVariable Long id,RedirectAttributes a){try{service.delete(id);a.addFlashAttribute("success","Xóa user thành công.");}catch(IllegalArgumentException e){a.addFlashAttribute("error",e.getMessage());}return "redirect:/users";}}
